import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

# ---------- Element-wise addition custom CUDA operator (reuse from example) ----------
elementwise_add_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>

__global__ void elementwise_add_kernel(const float* a, const float* b, float* out, int size) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx < size) {
        out[idx] = a[idx] + b[idx];
    }
}

torch::Tensor elementwise_add_cuda(torch::Tensor a, torch::Tensor b) {
    auto size = a.numel();
    auto out = torch::zeros_like(a);

    const int block_size = 256;
    const int num_blocks = (size + block_size - 1) / block_size;

    elementwise_add_kernel<<<num_blocks, block_size>>>(a.data_ptr<float>(), b.data_ptr<float>(), out.data_ptr<float>(), size);

    return out;
}
"""

elementwise_add_cpp_source = "torch::Tensor elementwise_add_cuda(torch::Tensor a, torch::Tensor b);"

elementwise_add = load_inline(
    name="elementwise_add",
    cpp_sources=elementwise_add_cpp_source,
    cuda_sources=elementwise_add_source,
    functions=["elementwise_add_cuda"],
    verbose=True,
    extra_cflags=[],
    extra_ldflags=[],
)

# ---------- LayerNorm custom CUDA operator ----------
layernorm_cuda_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>

__global__ void kernel_sum(const float* x, float* sum) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx < size) {
        sum[idx] += x[idx];
    }
}

__global__ void kernel_var(const float* x, const float* mean, float* var) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx < size) {
        float m = mean[idx];
        float diff = x[idx] - m;
        var[idx] += diff * diff;
    }
}

__global__ void kernel_norm(float* out, const float* x, const float* mean, const float* var) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx < size) {
        float m = mean[idx];
        float v = var[idx];
        float inv_sqrt_v = 1.0f / sqrtf((float)v + 1e-5f);
        out[idx] = (x[idx] - m) * inv_sqrt_v;
    }
}

torch::Tensor layernorm_cuda(torch::Tensor x) {
    auto size = x.numel();

    // Temporary device memory
    float* d_sum = new float[size]();
    float* d_mean = new float[size]();
    float* d_var  = new float[size]();
    float* d_out  = new float[size]();

    const int block_size = 256;
    const int num_blocks = (size + block_size - 1) / block_size;

    // 1. Sum
    kernel_sum<<<num_blocks, block_size>>>(x.data_ptr<float>(), d_sum);

    // 2. Mean: divide each sum by total elements
    __global__ void kernel_mean(const float* x, const float* sum, float* mean) {
        int idx = blockIdx.x * blockDim.x + threadIdx.x;
        if (idx < size) {
            mean[idx] = sum[idx] / static_cast<float>(size);
        }
    }
    kernel_mean<<<num_blocks, block_size>>>(x.data_ptr<float>(), d_sum, d_mean);

    // 3. Variance
    kernel_var<<<num_blocks, block_size>>>(x.data_ptr<float>(), d_mean, d_var);

    // 4. Normalize
    kernel_norm<<<num_blocks, block_size>>>(d_out, x.data_ptr<float>(), d_mean, d_var);

    // Copy result to output tensor on the same device as input
    torch::Tensor out = torch::empty(x.device, size, torch::kFloat);
    cudaMemcpy(out.data_ptr<float>(), d_out, size * sizeof(float), cudaMemcpyDeviceToDevice);

    return out;
}
"""

layernorm_cpp_source = "torch::Tensor layernorm_cuda(torch::Tensor x);"

layernorm = load_inline(
    name="layernorm",
    cpp_sources=layernorm_cpp_source,
    cuda_sources=layernorm_cuda_source,
    functions=["layernorm_cuda"],
    verbose=True,
    extra_cflags=[],
    extra_ldflags=[],
)

class ModelNew(nn.Module):
    def __init__(self):
        super().__init__()
        self.elementwise_add = elementwise_add
        self.layernorm = layernorm

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        return self.layernorm(x)
